// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.translationimport timber.log.Timberimport com.roshan.persona.voice.stt.SupportedLanguageimport com.roshan.persona.voice.stt.SttResultimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.launchimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport kotlinx.coroutines.yieldimport java.util.concurrent.atomic.AtomicBoolean/** * NOUS — Live Translation Engine (§10 Live Speech Translation). * * Sits between two speakers speaking different languages and translates * bidirectionally in real time. STT captures each speaker's words, the LLM * translates them, and TTS speaks the translation in NOUS's persona voice. * * ## Why persona voice, not cloned (§25 Q7) * * Per the confirmed decision Q7, live translation uses NOUS's persona voice * — NOT a voice clone of either speaker. Rationale: cloning adds ~1 s of * latency per utterance (VITS adaptation + synthesis), which would bust * the §15 latency budget of < 1.5 s for live translation. The persona * voice is already loaded and can synthesize immediately. * * ## Bidirectional mode (§10) * * Both directions run in parallel — Speaker A's utterances are translated * A→B and played to B, while Speaker B's utterances are translated B→A * and played to A. Speaker identification (Step 5.7 `SpeakerRecognitionEngine`) * routes each utterance to the correct direction; this class is agnostic * to how the speaker is identified — it just receives a stream of * `(speakerId, sttResult)` pairs. * * ## Latency budget (§15) * * Target: < 1.5 s per direction (speech-to-speech). * *  - STT final result:    ~500 ms (cloud) or ~1 s (offline) *  - LLM translation:     ~300 ms (cloud, short prompt) *  - TTS synthesis:       ~200 ms (persona voice, preloaded) *  - Total:               ~1.0–1.5 s ✓ * * If the latency exceeds the budget, [TranslatedUtterance.latencyMs] will * be larger than [LiveTranslationConfig.TARGET_LATENCY_MS] and the UI can * warn the user to switch to a faster STT engine. * * ## Testability * * All four collaborators (STT source, translate engine, TTS, speaker * router) are interfaces or already-testable wrappers. Tests inject a * fake STT source and a fake translate engine to verify the orchestration * logic without needing real audio or LLM. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§10 Live Speech Translation, §25 Q7, §15 Performance Budgets</a> */class LiveTranslationEngine(    private val tts: EmotionalTtsEngine,    private val personaProvider: () -> VoicePersona,    private val dispatcher: CoroutineDispatcher,    private val config: LiveTranslationConfig,) {    private val _state = MutableStateFlow(TranslationSessionState.IDLE)    /** Current session state — observe via [state]. */    val state: StateFlow<TranslationSessionState> = _state.asStateFlow()    private val _translations = MutableSharedFlow<TranslatedUtterance>(        extraBufferCapacity = 32,        onBufferOverflow = kotlinx.coroutines.channels.BufferOverflow.DROP_OLDEST,    )    /** Hot stream of completed translations. */    val translations: Flow<TranslatedUtterance> = _translations.asSharedFlow()    private val running = AtomicBoolean(false)    private var sessionJob: Job? = null    private val translationMutex = Mutex()  // serialize translations to avoid TTS overlap    /**     * Start the live translation session.     *     * The caller provides an [utteranceStream] — a hot flow of     * `(speaker, sttFinalResult)` pairs. Speaker identification (Step 5.7)     * is the caller's responsibility; this class just translates whatever     * it receives.     *     * Idempotent — calling twice is a no-op.     *     * @param utteranceStream  hot flow of (speaker, sttFinalResult) pairs.     * @param scope            coroutine scope to launch the session on.     */    fun startSession(        utteranceStream: Flow<SpeakerUtterance>,        scope: CoroutineScope,    ) {        if (!running.compareAndSet(false, true)) {            Timber.tag(TAG).w("startSession called while already running — ignoring.")            return        }        Timber.tag(TAG).i("Live translation session started: ${config.languageA} ↔ ${config.languageB}.")        _state.value = TranslationSessionState.LISTENING_A        sessionJob = scope.launch(dispatcher) {            try {                utteranceStream.collect { utterance ->                    if (!running.get()) return@collect                    handleUtterance(utterance)                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Translation session crashed", t)            } finally {                running.set(false)                _state.value = TranslationSessionState.ENDED                Timber.tag(TAG).i("Live translation session ended.")            }        }    }    /** End the session. Idempotent. */    fun stopSession() {        if (!running.compareAndSet(true, false)) return        sessionJob?.cancel()        sessionJob = null        _state.value = TranslationSessionState.ENDED    }    /** Pause the session — STT input is dropped until [resumeSession]. */    fun pauseSession() {        _state.value = TranslationSessionState.PAUSED    }    /** Resume a paused session. */    fun resumeSession() {        if (running.get() && _state.value == TranslationSessionState.PAUSED) {            _state.value = TranslationSessionState.LISTENING_A        }    }    // ──────────────────────────────────────────────────────────────────────    internal suspend fun handleUtterance(utterance: SpeakerUtterance) {        if (_state.value == TranslationSessionState.PAUSED) return        // Determine direction based on which speaker spoke.        val (from, to, direction) = when (utterance.speaker) {            Speaker.A -> Triple(config.languageA, config.languageB, TranslationDirection.A_TO_B)            Speaker.B -> Triple(config.languageB, config.languageA, TranslationDirection.B_TO_A)        }        // Skip if this direction is disabled.        if (config.direction != TranslationDirection.BIDIRECTIONAL && config.direction != direction) {            return        }        val engine = config.translateEngine ?: run {            Timber.tag(TAG).w("No translate engine configured — skipping utterance.")            return        }        translationMutex.withLock {            _state.value = TranslationSessionState.TRANSLATING            val startTime = System.currentTimeMillis()            // 1. Translate via LLM.            val translated = runCatching { engine.translate(utterance.text, from, to) }                .onFailure { Timber.tag(TAG).e("Translation failed", it) }                .getOrNull()            if (translated.isNullOrBlank()) {                Timber.tag(TAG).w("Translation returned empty — skipping TTS.")                _state.value = TranslationSessionState.LISTENING_A                return@withLock            }            // 2. Speak via TTS in NOUS's persona voice (NOT cloned, per §25 Q7).            _state.value = TranslationSessionState.SPEAKING            val persona = personaProvider()            tts.speak(                text = translated,                emotion = Emotion.NEUTRAL,  // translation is neutral — original emotion is in voice, not text                persona = persona,                activity = null,                onDone = {                    val latency = System.currentTimeMillis() - startTime                    val result = TranslatedUtterance(                        direction = direction,                        sourceText = utterance.text,                        sourceLanguage = from,                        translatedText = translated,                        targetLanguage = to,                        latencyMs = latency,                    )                    // SharedFlow.tryEmit is non-suspend — safe to call from onDone lambda.                    val emitOk = _translations.tryEmit(result)                    if (!emitOk) {                        Timber.tag(TAG).w("Failed to emit translation (buffer overflow).")                    }                    if (latency > LiveTranslationConfig.TARGET_LATENCY_MS) {                        Timber.tag(TAG).w("Translation latency ${latency}ms exceeds target ${LiveTranslationConfig.TARGET_LATENCY_MS}ms.")                    }                    _state.value = TranslationSessionState.LISTENING_A                },                onBargeIn = {                    _state.value = TranslationSessionState.LISTENING_A                },            )            yield()        }    }    private companion object {        private const val TAG = "LiveTranslation"    }}// ──────────────────────────────────────────────────────────────────────────/** Which speaker produced an utterance. */enum class Speaker { A, B }/** * One utterance from a speaker, identified by [SpeakerRecognitionEngine]. * * @param speaker  which speaker spoke. * @param text     the final STT result for the utterance. */data class SpeakerUtterance(    val speaker: Speaker,    val text: String,) {    init {        require(text.isNotBlank()) { "text must not be blank" }    }}
